from pathlib import Path

def scan_raw(root: Path) -> tuple[dict[str, int], dict[str, list[Path]]]:
    exts: dict[str, int] = {}
    by_tag: dict[str, list[Path]] = {}
    for path in root.rglob("*.md"):
        suf = path.suffix.lower()
        if suf not in exts:
            exts[suf] = 0
        exts[suf] += 1
        tag = path.stem.split("-")[0]
        if tag not in by_tag:
            by_tag[tag] = []
        by_tag[tag].append(path)
    return exts, by_tag
